/* prog17_whitespace_trim.c
 * Reimplementation of the behaviour observed in the obfuscated binary.
 *
 * - Takes the first command‑line argument.
 * - Considers only the first 0x400 (1024) bytes.
 * - Trims leading and trailing whitespace.
 * - Replaces each run of whitespace with a single space.
 * - Prints the result, or "EMPTY" if the result is empty or no argument was given.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    /* No argument → EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *src = argv[1];
    size_t len = strlen(src);
    if (len > 0x400)               /* truncate to 0x400 bytes */
        len = 0x400;

    char out[0x401];               /* enough for 0x400 chars + NUL */
    size_t out_len = 0;
    int have_output = 0;           /* have we already written a non‑space? */
    int prev_was_space = 0;        /* was the previous character whitespace? */

    for (size_t i = 0; i < len; ++i) {
        unsigned char ch = (unsigned char)src[i];
        if (isspace(ch)) {
            prev_was_space = 1;    /* remember we saw whitespace */
        } else {
            if (prev_was_space && have_output) {
                out[out_len++] = ' ';   /* collapse previous whitespace */
            }
            out[out_len++] = ch;        /* copy the non‑space character */
            have_output = 1;
            prev_was_space = 0;
        }
    }

    out[out_len] = '\0';

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }

    return 0;
}
